import requests
import json

# Abstracted provider-specific request/response handling
class ProviderClient:
    def __init__(self):
        self.api_url = "https://api.provider.com/v1/extract"  # Example provider API endpoint

    def extract(self, document):
        response = requests.post(self.api_url, files={"file": document})
        if response.status_code != 200:
            raise Exception("Extraction failed with status code {}".format(response.status_code))

        return response.json() 

def normalize_expense_fields(extracted_data):
    # Normalize extracted data into the standard JSON schema
    normalized_data = {
        "amount": extracted_data["amount"],
        "merchant": extracted_data["merchant"],
        "date": extracted_data["date"],
        "currency": extracted_data["currency"]
    }
    return json.dumps(normalized_data)

# Usage
if __name__ == "__main__":
    client = ProviderClient()

    # Load document to be processed
    with open("expense_document.jpg", "rb") as file:
        extracted_data = client.extract(file)

    normalized_json = normalize_expense_fields(extracted_data)
    print(normalized_json)
